    whyBody: "Վաճառքները ցրված են շրջանային կայքերում, դատական ծանուցումներում և պետական հարթակներում։ Որոշ գնորդներ հաղթում են աճուրդում, ապա պարզում են, որ գույքի վրա մնում է երկրորդ հիփոթեքը կամ նախկին սեփականատերը գույքը հետ գնելու ժամկետ ունի։ Մենք համախմբում ենք վաճառքները մեկ ցանկում, քարտեզում և օրացույցում ու յուրաքանչյուրի կողքին ցույց տալիս այդ ռիսկերը։",
